source('R/stile.R')
d<-leggi('co2_1985_2001.csv');d$data<-as.Date(d$data);y<-ts(d$co2_ppm,start=c(1985,1),frequency=12);tr<-window(y,end=c(1998,12));te<-window(y,start=c(1999,1));h<-length(te);nt<-length(tr)
mod<-arima(tr,order=c(0,1,1),seasonal=list(order=c(0,1,1),period=12),include.mean=FALSE,method='ML');stopifnot(mod$code==0)
f<-predict(mod,n.ahead=h);prev<-as.numeric(f$pred);se<-as.numeric(f$se);lo<-prev-qnorm(.975)*se;hi<-prev+qnorm(.975)*se
metodi<-list(Ultimo=rep(as.numeric(tail(tr,1)),h),Stagionale=rep(as.numeric(tail(tr,12)),length.out=h),Deriva=as.numeric(tail(tr,1))+(1:h)*(as.numeric(tail(tr,1))-as.numeric(head(tr,1)))/(nt-1),SARIMA=prev)
val<-data.frame(Metodo=names(metodi),MAE=vapply(metodi,function(z)mean(abs(as.numeric(te)-z)),0.0),RMSE=vapply(metodi,function(z)sqrt(mean((as.numeric(te)-z)^2)),0.0));print(val)
z<-data.frame(data=d$data[(nt+1):nrow(d)],Osservato=as.numeric(te),Previsto=prev,Basso=lo,Alto=hi)
p<-ggplot(z,aes(data,Previsto))+geom_ribbon(aes(ymin=Basso,ymax=Alto),fill=geo[1],alpha=.2)+geom_line(colour=geo[1],linewidth=.9)+geom_line(aes(y=Osservato),colour=geo[2],linewidth=.7)+scale_x_date(breaks=as.Date(c('1999-01-01','2000-01-01','2001-01-01')),date_labels='%Y')+labs(x='Anno del test',y='CO₂ (ppm)')
salva('M10','F01',p)
z1<-do.call(rbind,lapply(names(metodi),function(k)data.frame(data=z$data,Valore=metodi[[k]],Metodo=k)))
salva('M10','F02',ggplot(z1,aes(data,Valore,colour=Metodo))+geom_line(linewidth=.8)+geom_line(data=z,aes(data,Osservato),inherit.aes=FALSE,colour=geo[6],linewidth=.55)+scale_colour_manual(values=geo[c(3,1,2,4)])+guides(colour=guide_legend(nrow=2))+scale_x_date(breaks=as.Date(c('1999-01-01','2000-01-01','2001-01-01')),date_labels='%Y')+labs(x='Anno del test',y='CO₂ prevista (ppm)'))
salva('M10','F03',ggplot(val,aes(reorder(Metodo,RMSE),RMSE))+geom_col(fill=geo[1],width=.6)+coord_flip()+labs(x=NULL,y='RMSE sul test (ppm)'))
r<-as.numeric(residuals(mod))[14:nt];dr<-data.frame(data=d$data[14:nt],Residuo=r)
salva('M10','F04',ggplot(dr,aes(data,Residuo))+geom_hline(yintercept=0,colour=geo[6])+geom_line(colour=geo[1],linewidth=.6)+scale_x_date(date_breaks='5 years',date_labels='%Y')+labs(x='Anno del training',y='Innovazione (ppm)'))
a<-acf(r,plot=FALSE,lag.max=24);da<-data.frame(Lag=1:24,ACF=as.numeric(a$acf)[-1])
salva('M10','F05',ggplot(da,aes(Lag,ACF))+geom_segment(aes(xend=Lag,yend=0),colour=geo[1],linewidth=.8)+geom_hline(yintercept=0,colour=geo[6])+geom_hline(yintercept=c(-1,1)*1.96/sqrt(length(r)),linetype=2,colour=geo[2])+scale_x_continuous(breaks=c(1,6,12,18,24))+labs(x='Ritardo (mesi)',y='ACF dei residui'))
salva('M10','F06',ggplot(dr,aes(sample=Residuo))+stat_qq(colour=geo[1],size=1.6)+stat_qq_line(colour=geo[2],linewidth=.8)+labs(x='Quantile normale',y='Residuo (ppm)'))
z$Errore<-z$Osservato-z$Previsto
salva('M10','F07',ggplot(z,aes(data,Errore))+geom_hline(yintercept=0,colour=geo[6])+geom_line(colour=geo[2],linewidth=.9)+scale_x_date(breaks=as.Date(c('1999-01-01','2000-01-01','2001-01-01')),date_labels='%Y')+labs(x='Anno del test',y='Errore (ppm)'))
cv<-do.call(rbind,lapply(c(120,132,144),function(o){tt<-ts(as.numeric(tr)[1:o],start=c(1985,1),frequency=12);oo<-as.numeric(tr)[o+1:12];mm<-arima(tt,order=c(0,1,1),seasonal=list(order=c(0,1,1),period=12),include.mean=FALSE,method='ML');stopifnot(mm$code==0);pr<-as.numeric(predict(mm,n.ahead=12)$pred);data.frame(Anno=1984+o/12,Metodo=c('SARIMA','Stagionale'),RMSE=c(sqrt(mean((oo-pr)^2)),sqrt(mean((oo-as.numeric(tail(tt,12)))^2))))}))
salva('M10','F08',ggplot(cv,aes(Anno,RMSE,colour=Metodo))+geom_line(linewidth=.9)+geom_point(size=2.8)+scale_colour_manual(values=geo[1:2])+scale_x_continuous(breaks=c(1994,1995,1996))+labs(x='Anno dell’origine interna',y='RMSE a 12 mesi (ppm)'))
phi<-.65;hh<-0:12;aa<-data.frame(h=hh,Media=2*phi^hh,SE=sqrt((1-phi^(2*hh))/(1-phi^2)))
salva('M10','F09',ggplot(aa,aes(h,Media))+geom_ribbon(aes(ymin=Media-1.96*SE,ymax=Media+1.96*SE),fill=geo[1],alpha=.15)+geom_line(colour=geo[1],linewidth=1)+geom_point(colour=geo[1],size=2)+geom_hline(yintercept=0,linetype=2,colour=geo[6])+scale_x_continuous(breaks=c(0,3,6,9,12))+scale_y_continuous(breaks=c(-2,0,2))+labs(x='Orizzonte (passi)',y='AR(1): previsione e banda'))
p<-leggi('processi_simulati.csv');dv<-data.frame(y=tail(p$y_VAR,-1),yl=head(p$y_VAR,-1),xl=head(p$x_VAR,-1));rid<-lm(y~yl,dv);com<-lm(y~yl+xl,dv);test<-anova(rid,com);print(coef(com));print(test)
A<-matrix(c(.5,0,.6,.35),nrow=2,byrow=TRUE);ir<-sapply(0:8,function(h){B<-diag(2);if(h>0)for(i in 1:h)B<-B%*%A;B%*%c(1,0)});dz<-data.frame(Passo=rep(0:8,2),Risposta=c(ir[1,],ir[2,]),Variabile=rep(c('X','Y'),each=9))
salva('M10','F10',ggplot(dz,aes(Passo,Risposta,colour=Variabile))+geom_line(linewidth=.9)+geom_point(size=2.3)+scale_colour_manual(values=geo[1:2])+scale_x_continuous(breaks=c(0,2,4,6,8))+labs(x='Passi dallo shock in X',y='Risposta del generatore'))
lj<-Box.test(r,lag=24,type='Ljung-Box',fitdf=2);cop<-mean(as.numeric(te)>=lo&as.numeric(te)<=hi)
dir.create('risultati/M10',recursive=TRUE,showWarnings=FALSE);write.csv(val,'risultati/M10/metriche.csv',row.names=FALSE);write.csv(z,'risultati/M10/previsioni.csv',row.names=FALSE);write.csv(cv,'risultati/M10/validazione_interna.csv',row.names=FALSE)
jsonlite::write_json(list(coef=as.list(coef(mod)),sigma2=mod$sigma2,Ljung_Q=unname(lj$statistic),Ljung_df=unname(lj$parameter),Ljung_p=lj$p.value,copertura=cop,ampiezza_media=mean(hi-lo),Granger_F=test$F[2],Granger_p=test$`Pr(>F)`[2],VAR_coef=as.list(coef(com))), 'risultati/M10/valori.json',auto_unbox=TRUE,pretty=TRUE,digits=15)
verifica('train e test cronologici',nt==168 && h==36 && d$data[nt]<min(z$data))
verifica('orizzonte e date',length(prev)==36 && all(is.finite(prev)) && all(se>0))
verifica('bande ordinate',all(lo<prev & hi>prev))
verifica('ricorsione AR1',abs(aa$Media[2]-1.3)<1e-12 && abs(aa$Media[3]-.845)<1e-12)
verifica('varianza AR1',max(abs(aa$SE^2-vapply(hh,function(h)if(h==0)0 else sum(phi^(2*(0:(h-1)))),0.0)))<1e-12)
Q<-length(r)*(length(r)+2)*sum(da$ACF^2/(length(r)-1:24));verifica('Ljung Box esplicito',abs(Q-unname(lj$statistic))<1e-10)
Fman<-((deviance(rid)-deviance(com))/(df.residual(rid)-df.residual(com)))/(deviance(com)/df.residual(com));verifica('test F annidato',abs(Fman-test$F[2])<1e-10)
verifica('stabilità VAR generatore',max(Mod(eigen(A)$values))<1)
print(lj);cat('Copertura test:',cop,'\n')
